){


    companion object
}

/**
 * @suppress
 */
object FfiConverterTypeFrameRegion: FfiConverterRustBuffer<FrameRegion> {
    override fun read(buf: ByteBuffer): FrameRegion {
        return FrameRegion(
            FfiConverterUShort.read(buf),
            FfiConverterUShort.read(buf),
            FfiConverterUShort.read(buf),
            FfiConverterUShort.read(buf),
            FfiConverterByteArray.read(buf)
        )
    }

    override fun allocationSize(value: FrameRegion) = (
            FfiConverterUShort.allocationSize(value.x) +
            FfiConverterUShort.allocationSize(value.y) +
            FfiConverterUShort.allocationSize(value.width) +
            FfiConverterUShort.allocationSize(value.height) +
            FfiConverterByteArray.allocationSize(value.argb)
    )

    override fun write(value: FrameRegion, buf: ByteBuffer) {
            FfiConverterUShort.write(value.x, buf)
            FfiConverterUShort.write(value.y, buf)
            FfiConverterUShort.write(value.width, buf)
            FfiConverterUShort.write(value.height, buf)
            FfiConverterByteArray.write(value.argb, buf)
    }
}


