enum class MouseButton {

    LEFT,
    RIGHT,
    MIDDLE;


    companion object
}


/**
 * @suppress
 */
object FfiConverterTypeMouseButton: FfiConverterRustBuffer<MouseButton> {
    override fun read(buf: ByteBuffer) = try {
        MouseButton.entries[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: MouseButton) = 4UL

    override fun write(value: MouseButton, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}


enum class SessionState {

    CONNECTING,
    CONNECTED,
    DISCONNECTED,
    FAILED;


    companion object
}


/**
 * @suppress
 */
object FfiConverterTypeSessionState: FfiConverterRustBuffer<SessionState> {
    override fun read(buf: ByteBuffer) = try {
        SessionState.entries[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: SessionState) = 4UL

    override fun write(value: SessionState, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}


/**
 * @suppress
 */
object FfiConverterOptionalTypeFrameUpdate: FfiConverterRustBuffer<FrameUpdate?> {
    override fun read(buf: ByteBuffer): FrameUpdate? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterTypeFrameUpdate.read(buf)
    }

    override fun allocationSize(value: FrameUpdate?): ULong {
        if (value == null) {
            return 1UL
        }
        return 1UL + FfiConverterTypeFrameUpdate.allocationSize(value)
    }

    override fun write(value: FrameUpdate?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterTypeFrameUpdate.write(value, buf)
        }
    }
}


/**
 * @suppress
 */
object FfiConverterSequenceTypeFrameRegion: FfiConverterRustBuffer<List<FrameRegion>> {
    override fun read(buf: ByteBuffer): List<FrameRegion> {
        val len = buf.getInt()
        return List(len) {
            FfiConverterTypeFrameRegion.read(buf)
        }
    }

    override fun allocationSize(value: List<FrameRegion>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.sumOf { FfiConverterTypeFrameRegion.allocationSize(it) }
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<FrameRegion>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.forEach {
            FfiConverterTypeFrameRegion.write(it, buf)
        }
    }
}
